/*
 * أسئلةُ نقل الملكيّة في أبشر — تُدرَج في قاعدةٍ قائمة.
 *
 * وبذرةُ المنصّة لا تقع إلّا على قاعدةٍ **فارغة** (`importSeed` تردّ على
 * قاعدةٍ فيها بيانات)، فأسئلةٌ تُضاف إلى البذرة لا تصل منصّةً تعمل. وهذه
 * أربعةٌ تُسأل في كلّ صفقة: كيف ينقل البائع، وكيف يستلم المشتري، وهل
 * تلزم المحفظة الرقميّة، ومن يدفع رسوم أبشر.
 *
 * **ويُدرَج بلا تكرار** (`WHERE NOT EXISTS`) على نصّ السؤال: فترحيلٌ
 * يُعاد تشغيله — أو إدارةٌ أضافت السؤالَ بيدها قبله — لا يُنتج نسختين في
 * صفحةٍ واحدة. ومعرّفاتٌ ثابتةٌ (`faq_absher_*`) تجعل الصفَّ معروفًا إن
 * احتيج تعديلُه لاحقًا.
 *
 * وما تحرّره الإدارةُ بعد ذلك يبقى كما حرّرته — لا يعيده ترحيلٌ تالٍ.
 */

INSERT INTO "faq" ("id","question","answer","category","sort_order","published","show_on_sale_types","created_at","updated_at")
SELECT 'faq_absher_12', 'كيف أنقل اللوحة للمشتري في أبشر؟ (للبائع)', 'بعد أن يصل مبلغ المشتري ويُحجز أمانةً لدى المنصّة يأتي دورك: ادخل أبشر أفراد، ثمّ المركبات ← محفظة لوحات المركبات الرقمية، واختر اللوحة المباعة، ثمّ خدمة «نقل اللوحات» ونوع الطلب «نقل إلى مالك آخر». أدخِل رقم هوية المشتري أو إقامته وتاريخ ميلاده — وراجِعهما قبل الإرسال — ثمّ أكّد الطلب. يصل المشتري إشعارٌ فوريٌّ بطلبٍ معلّقٍ بانتظار موافقته. وبعد قبوله ارفع إثبات النقل في صفحة صفقتك لتتحقّق منه الإدارة ويُحوَّل إليك المبلغ. **والخطوات نفسُها معروضةٌ داخل صفحة صفقتك في وقتها.**', 'selling', 12, true,
       '["auction","fixed","offers"]'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM "faq" WHERE "question" = 'كيف أنقل اللوحة للمشتري في أبشر؟ (للبائع)');

INSERT INTO "faq" ("id","question","answer","category","sort_order","published","show_on_sale_types","created_at","updated_at")
SELECT 'faq_absher_13', 'كيف أستلم اللوحة في أبشر؟ (للمشتري)', 'بعد أن يُرسل البائع طلب النقل يصلك إشعارٌ من أبشر. ادخل أبشر أفراد، ثمّ المركبات ← محفظة لوحات المركبات الرقمية، واستعرض الطلبات الواردة أو المعلّقة، ثمّ وافق على طلب نقل اللوحة واقبله — فتدخل اللوحة محفظتك فورًا وتصير مملوكةً لك رسميًّا. ولا يُحوَّل مبلغك إلى البائع إلّا بعد أن ترفع الإدارةُ تحقّقها من النقل.', 'payment', 13, true,
       '["auction","fixed","offers"]'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM "faq" WHERE "question" = 'كيف أستلم اللوحة في أبشر؟ (للمشتري)');

INSERT INTO "faq" ("id","question","answer","category","sort_order","published","show_on_sale_types","created_at","updated_at")
SELECT 'faq_absher_14', 'هل لا بدّ أن تكون اللوحة في محفظتي الرقمية قبل بيعها؟', 'نعم. لا يظهر خيارُ نقل اللوحة مجرّدةً (بلا سيارة) في أبشر إلّا إذا كانت في محفظة لوحات المركبات الرقمية. وتصل محفظتك بإحدى حالتين: أن تكون اشتريتها من مزاد المرور ونزلت إليها مباشرةً، أو أن تكون راكبةً على سيّارتك فتفصلها إليها. والفصل: المركبات ← محفظة لوحات المركبات الرقمية ← «إضافة لوحة من مركبة إلى المحفظة»، ثمّ تحدّد السيّارة وتوافق على سحب اللوحة — وتُصرَف لسيّارتك لوحةٌ تنظيميّةٌ بديلة. **افعل ذلك قبل العرض أو فور رسو الصفقة**، فلوحةٌ ما زالت على سيّارتك لا تُنقل.', 'selling', 14, true,
       '["auction","fixed","offers"]'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM "faq" WHERE "question" = 'هل لا بدّ أن تكون اللوحة في محفظتي الرقمية قبل بيعها؟');

INSERT INTO "faq" ("id","question","answer","category","sort_order","published","show_on_sale_types","created_at","updated_at")
SELECT 'faq_absher_15', 'ما رسوم أبشر؟ ومن يدفعها — البائع أم المشتري؟', 'رسومٌ حكوميّةٌ تُدفع في سداد ولا تمرّ بالمنصّة ولا تدخل حسابها، وهي غير عمولة المنصّة. وهما رسمان: **تفعيل محفظة اللوحات الرقمية — 402 ريال**، يدفعها كلُّ طرفٍ عن نفسه مرّةً واحدةً فقط (البائع ليحفظ لوحاته ويعرضها، والمشتري ليستقبلها في محفظته)؛ و**نقل ملكية اللوحة — 230 ريال**، يتحمّلها المشتري بالكامل وفق العرف السائد وشروط المنصّة، ما لم يُتّفق على غير ذلك. وهذه أرقامُ تعرفة أبشر الحالية وقد تتغيّر بقرار الجهة.', 'payment', 15, true,
       '["auction","fixed","offers"]'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM "faq" WHERE "question" = 'ما رسوم أبشر؟ ومن يدفعها — البائع أم المشتري؟');
